    delimiter: str | None = None
    no_sort: bool = False
    literal: bool = False
    tail: int | None = None
    disabled: bool = False
    tiebreak: list = field(default_factory=lambda: ['length'])
    read0: bool = False
    print0: bool = False
    ansi: bool = False
    sync: bool = False
    height: str | None = None
    min_height: str | None = None
    tmux: str | None = None
    layout: str = 'default'
    multi: int | None = None
    multi_enabled: bool = False
    tac: bool = False
    header_lines: int = 0
    header: str | None = None
    filter_query: str | None = None
    query: str = ''
    select1: bool = False
    exit0: bool = False
    print_query: bool = False
    expect: list = field(default_factory=list)
    show_version: bool = False
    show_help: bool = False
    show_man: bool = False
    shell: str | None = None
    walker_opts: set = field(default_factory=lambda: {'file','follow','hidden'})
    walker_root: list = field(default_factory=list)
    walker_skip: list = field(default_factory=lambda: ['.git','node_modules'])
    prompt: str = '> '

# ----------------------------- Utilities -----------------------------

def eprint(msg):
    sys.stderr.write(str(msg) + "\n")

def strip_ansi(s: str) -> str:
    return ANSI_RE.sub('', s)

def remove_accents(s: str) -> str:
    # fzf normalizes latin letters unless --literal is set. NFKD is not byte-for-byte
    # identical to fzf's table, but it captures the visible behavior for common input.
    return ''.join(c for c in unicodedata.normalize('NFKD', s) if not unicodedata.combining(c))

def has_upper(s: str) -> bool:
    return any(ch.isalpha() and ch.upper() == ch and ch.lower() != ch for ch in s)

def normalize_for_match(s: str, ignore_case: bool, literal: bool) -> str:
    if not literal:
        s = remove_accents(s)
    if ignore_case:
        s = s.lower()
    return s

def shell_split_options(text: str, source: str):
    try:
        return shlex.split(text, comments=False, posix=True)
    except ValueError as ex:
        raise FzfError(f"{source}: {ex}")

def output_bytes(parts, opt: Options):
    delim = b'\0' if opt.print0 else b'\n'
    out = bytearray()
    for part in parts:
        if isinstance(part, bytes):
            out.extend(part)
        else:
            out.extend(str(part).encode('utf-8', 'surrogateescape'))
        out.extend(delim)
    sys.stdout.buffer.write(bytes(out))

