def parse_int_value(val, msg_prefix='not a valid integer'):
    try:
        return int(val)
    except Exception:
        raise FzfError(f"{msg_prefix}: {val}")

def validate_height(val):
    v = val
    if v.startswith('~'):
        v = v[1:]
    if v.endswith('%'):
        v = v[:-1]
    if v.startswith('--'):
        v = v[1:]  # observed: --filter=foo -> -filter=foo in error
    if v in ('','-','+'):
        raise FzfError(f"not a valid integer: {v}")
    try:
        int(v)
    except Exception:
        raise FzfError(f"not a valid integer: {v}")

def validate_nonneg_int_plus(val, err):
    v = val[:-1] if val.endswith('+') else val
    try:
        n = int(v)
        if n < 0:
            raise ValueError
    except Exception:
        raise FzfError(err)

def validate_field_expr_atom(expr: str):
    if expr == '':
        raise FzfError('invalid format: ' + expr)
    if '..' in expr:
        if expr.count('..') != 1:
            raise FzfError('invalid format: ' + expr)
        a,b = expr.split('..')
        for x in (a,b):
            if x == '':
                continue
            try:
                n = int(x)
            except Exception:
                raise FzfError('invalid format: ' + expr)
            if n == 0:
                raise FzfError('invalid format: ' + expr)
    else:
        try:
            n = int(expr)
        except Exception:
            raise FzfError('invalid format: ' + expr)
        if n == 0:
            raise FzfError('invalid format: ' + expr)

def valid_placeholder(content: str) -> bool:
    if content == 'n':
        return True
    try:
        validate_field_expr_atom(content)
        return True
    except FzfError:
        return False

def validate_nth_template(s: str):
    if '{' in s and '}' in s:
        good = False
        for m in re.finditer(r'\{([^{}]+)\}', s):
            if valid_placeholder(m.group(1)):
                good = True
        if not good:
            # fzf reports the given template in the message
            raise FzfError(f"template should include at least 1 placeholder: {s}")
        return
    for part in s.split(','):
        validate_field_expr_atom(part)

def validate_tiebreak(val):
    allowed = {'length','chunk','pathname','begin','end','index'}
    parts = val.split(',') if val != '' else ['']
    seen = set()
    for i,p in enumerate(parts):
        if p not in allowed:
            raise FzfError('invalid sort criterion: ' + p)
        if p in seen:
            raise FzfError('duplicate sort criteria: ' + p)
        seen.add(p)
        if p == 'index' and i != len(parts)-1:
            raise FzfError('index should be the last criterion')
    return parts

def validate_bind(val):
    # Filter mode ignores bindings, but fzf validates obvious malformed input.
    for binding in split_bindings(val):
        if ':' not in binding:
            raise FzfError('bind action not specified: ' + binding)
        _, action = binding.split(':', 1)
        if not action:
            raise FzfError('bind action not specified: ' + binding)
        # Multiple actions can be chained with +. Action arguments use (...) or :...
        for act in re.split(r'(?<!\\)\+', action):
            name = act.strip()
            if not name:
                continue
            name = name.split(':',1)[0]
            name = name.split('(',1)[0]
            if name and name not in ACTIONS:
                raise FzfError('unknown action: ' + name)

def split_bindings(s):
    # Split on commas not inside parentheses.
    out=[]; buf=[]; depth=0; esc=False
    for ch in s:
        if esc:
            buf.append(ch); esc=False; continue
        if ch == '\\':
            buf.append(ch); esc=True; continue
        if ch == '(':
            depth += 1
        elif ch == ')' and depth:
            depth -= 1
        if ch == ',' and depth == 0:
            out.append(''.join(buf)); buf=[]
        else:
            buf.append(ch)
    out.append(''.join(buf))
    return out

def validate_color(val):
    bases = {'dark','light','base16','16','bw','no','default'}
    # A lone unknown atom is rejected; most color maps contain ':' and are accepted.
    atoms = re.split(r'[\s,]+', val.strip())
    for a in atoms:
        if not a:
            continue
        if ':' in a or a in bases or a.startswith('fg') or a.startswith('bg'):
            continue
        raise FzfError('invalid color specification: ' + a)

def validate_preview_window(val):
    valid = {'up','down','left','right','hidden','nohidden','wrap','nowrap','cycle','nocycle','follow','nofollow','info','noinfo','default'}
    for part in val.split(','):
        if part == '' or part.endswith('%') or part.isdigit() or part.startswith('+') or part.startswith('~') or part.startswith('<') or part.startswith('border-'):
            continue
        if ':' in part:  # layout:size or threshold(alternative)
            continue
        if part not in valid:
            raise FzfError('invalid preview window option: ' + part)

def take_value(args, i, optname, attached=None):
    if attached is not None:
        return attached, i
    if i + 1 >= len(args):
        raise FzfError(REQUIRES_VALUE.get(optname, 'argument required'))
    return args[i+1], i+1

def apply_option(opt: Options, name: str, value, source_prefix=''):
    if name in ('--version',): opt.show_version=True; return
    if name in ('--help','-h'): opt.show_help=True; return
    if name == '--man': opt.show_man=True; return
    if name == '--bash': opt.shell='bash'; return
    if name == '--zsh': opt.shell='zsh'; return
    if name == '--fish': opt.shell='fish'; return
    if name in ('--exact','-e'): opt.exact=True; return
    if name in ('--extended','-x'): opt.extended=True; return
    if name in ('--no-extended','+x'): opt.extended=False; return
    if name in ('--ignore-case','-i'): opt.case_mode='ignore'; return
    if name in ('--no-ignore-case','+i'): opt.case_mode='respect'; return
    if name == '--smart-case': opt.case_mode='smart'; return
    if name in ('--no-sort','+s'): opt.no_sort=True; return
    if name == '--literal': opt.literal=True; return
    if name == '--disabled': opt.disabled=True; return
    if name == '--read0': opt.read0=True; return
    if name == '--print0': opt.print0=True; return
    if name == '--ansi': opt.ansi=True; return
    if name == '--sync': opt.sync=True; return
    if name == '--tac': opt.tac=True; return
    if name in ('--select-1','-1'): opt.select1=True; return
    if name in ('--exit-0','-0'): opt.exit0=True; return
    if name == '--print-query': opt.print_query=True; return
    if name == '+m': opt.multi_enabled=False; opt.multi=None; return
    if name in ('--query','-q'): opt.query=value; return
    if name in ('--filter','-f'): opt.filter_query=value; return
    if name in ('--prompt',): opt.prompt=value; return
    if name == '--scheme':
        if value not in ('default','path','history'):
            raise FzfError(f"invalid scoring scheme: {value} (expected: default|path|history)")
        opt.scheme=value
        if value == 'path':
            opt.tiebreak = ['pathname','length']
        elif value == 'history':
            opt.tiebreak = ['index']
        return
    if name == '--algo':
        if value not in ('v1','v2'):
            raise FzfError('invalid algorithm (expected: v1 or v2)')
        opt.algo=value; return
    if name in ('--nth','-n'):
        validate_nth_template(value); opt.nth=value; return
    if name == '--with-nth':
        validate_nth_template(value); opt.with_nth=value; return
    if name == '--accept-nth':
        validate_nth_template(value); opt.accept_nth=value; return
    if name in ('--delimiter','-d'): opt.delimiter=value; return
    if name == '--tail':
        try:
            n=int(value)
            if n < 0: raise ValueError
        except Exception:
            raise FzfError('number of items to keep required')
        opt.tail=n; return
    if name == '--tiebreak': opt.tiebreak=validate_tiebreak(value); return
    if name == '--height': validate_height(value); opt.height=value; return
    if name == '--min-height': validate_nonneg_int_plus(value, 'minimum height must be a non-negative integer'); opt.min_height=value; return
    if name in ('--multi','-m'):
        opt.multi_enabled=True
        if value is not None:
            try:
                n=int(value)
            except Exception:
                raise FzfError('not a valid integer: ' + value)
            opt.multi=n
        return
    if name == '--header-lines':
        try:
            n=int(value)
            if n < 0: raise ValueError
        except Exception:
            raise FzfError('number of header lines required')
        opt.header_lines=n; return
    if name == '--header': opt.header=value; return
    if name == '--expect': opt.expect=[k for k in value.split(',') if k!='']; return
    if name == '--layout':
        if value not in ('default','reverse','reverse-list'):
            raise FzfError('invalid layout (expected: default / reverse / reverse-list)')
        opt.layout=value; return
    if name == '--info':
        if not (value in ('default','right','hidden') or value.startswith('inline')):
            raise FzfError('invalid info style (expected: default|right|hidden|inline[-right][:PREFIX])')
        return
    if name in ('--border','--list-border','--input-border','--preview-border','--header-border','--header-lines-border','--footer-border'):
        if value is not None and value not in BORDER_STYLES:
            raise FzfError(f"invalid border style (expected: {BORDER_STYLES_ERR})")
        return
    if name == '--style':
        if not (value in ('default','minimal','full') or value.startswith('full:')):
            # fzf accepts many combinations; reject only obviously malformed presets.
            raise FzfError('invalid style preset: ' + value)
        return
    if name == '--color': validate_color(value); return
    if name == '--preview-window': validate_preview_window(value); return
    if name == '--bind': validate_bind(value); return
    if name == '--walker':
        opts=set()
        for p in value.split(','):
            if p not in ('file','dir','follow','hidden'):
                raise FzfError('invalid walker option: ' + p)
            opts.add(p)
        opt.walker_opts=opts; return
    if name == '--walker-skip':
        opt.walker_skip=[p for p in value.split(',') if p!='']; return
    if name == '--walker-root':
        opt.walker_root.append(value); return
    if name == '--history-size':
        try: int(value)
        except Exception: raise FzfError('history size must be a non-negative integer')
        return
    if name in ('--gap','--freeze-left','--freeze-right','--scroll-off','--hscroll-off','--tabstop'):
        if value is not None:
            parse_int_value(value)
        return
    # Recognized but behavior is purely interactive/cosmetic in this reimplementation.
    return

def parse_args(argv):
    opt = Options()
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == '--':
            i += 1; continue
        if arg.startswith('--'):
            if '=' in arg:
                name, val = arg.split('=',1)
            else:
                name, val = arg, None
            # Special multi-root option consumes one or more following non-options.
            if name == '--walker-root':
                if val is not None:
                    apply_option(opt, name, val)
                else:
                    if i+1 >= len(argv):
                        raise FzfError('walker root required')
                    j=i+1
                    while j < len(argv) and not argv[j].startswith('-') and not argv[j].startswith('+'):
                        apply_option(opt, name, argv[j]); j += 1
                    i = j-1
                i += 1; continue
            if name in NO_VALUE:
                if val is not None:
                    # most no-value fzf flags reject --flag=value as unknown option syntax
                    raise FzfError('unknown option: ' + arg)
                apply_option(opt, name, None); i += 1; continue
            if name in OPTIONAL_VALUE:
                if val is None:
                    # optional values are only consumed when the next token is a plain word
                    if i+1 < len(argv) and not argv[i+1].startswith('-') and not argv[i+1].startswith('+'):
                        val=argv[i+1]; i += 1
                    else:
                        val=None
                apply_option(opt, name, val); i += 1; continue
            if name in REQUIRES_VALUE or name in REQUIRES_VALUE.keys():
                val, i = take_value(argv, i, name, val)
                apply_option(opt, name, val); i += 1; continue
            # Long options that require values but are not in REQUIRES_VALUE aliases
            known_value_prefixes = {
                '--margin','--padding','--border-label','--border-label-pos','--list-label','--list-label-pos',
                '--input-label','--input-label-pos','--preview-label','--preview-label-pos','--header-label','--header-label-pos',
                '--footer','--footer-label','--footer-label-pos','--preview','--history','--with-shell','--listen',
                '--jump-labels','--gutter','--gutter-raw','--pointer','--marker','--marker-multi-line','--ellipsis',
                '--wrap-sign','--gap-line','--info-command','--separator','--ghost','--scrollbar'
            }
            if name in known_value_prefixes:
                if name in OPTIONAL_VALUE:
                    if val is None and i+1 < len(argv) and not argv[i+1].startswith('-') and not argv[i+1].startswith('+'):
                        val=argv[i+1]; i+=1
                else:
                    val, i = take_value(argv, i, name, val)
                apply_option(opt, name, val); i += 1; continue
            raise FzfError('unknown option: ' + arg)
        elif arg.startswith('+'):
            if arg in NO_VALUE:
                apply_option(opt, arg, None); i += 1; continue
            raise FzfError('unknown option: ' + arg)
        elif arg.startswith('-') and arg != '-':
            # Short options: value can be attached for -f, -q, -n, -d, -m.
            if arg in NO_VALUE:
                apply_option(opt, arg, None); i += 1; continue
            ch = arg[:2]
            rest = arg[2:]
            if ch in ('-f','-q','-n','-d'):
                val = rest if rest != '' else None
                val, i = take_value(argv, i, ch, val)
                apply_option(opt, ch, val); i += 1; continue
            if ch == '-m':
                val = rest if rest != '' else None
                if val is None and i+1 < len(argv) and re.fullmatch(r'\d+', argv[i+1] or ''):
                    val=argv[i+1]; i += 1
                apply_option(opt, '-m', val); i += 1; continue
            raise FzfError('unknown option: ' + arg)
        else:
            raise FzfError('unknown option: ' + arg)
    return opt

# ----------------------------- Input and fields -----------------------------

@dataclass
class Item:
    original: str
    ordinal: int
    order: int
    display: str = ''
    search: str = ''
    output: str = ''

def read_records(opt: Options):
    if sys.stdin.isatty():
        data = get_tty_input(opt)
    else:
        data = sys.stdin.buffer.read()
    sep = b'\0' if opt.read0 else b'\n'
    if data == b'':
        return []
    parts = data.split(sep)
    if data.endswith(sep):
        parts = parts[:-1]
    return [p.decode('utf-8','surrogateescape') for p in parts]

def get_tty_input(opt: Options):
    cmd = os.environ.get('FZF_DEFAULT_COMMAND')
    if cmd:
        try:
            return subprocess.check_output(cmd, shell=True, stderr=subprocess.DEVNULL)
        except subprocess.CalledProcessError as ex:
            return ex.output or b''
    # Built-in walker when stdin is a TTY.
    roots = opt.walker_root or ['.']
    lines=[]
    include_files = 'file' in opt.walker_opts
    include_dirs = 'dir' in opt.walker_opts
    traverse_hidden = 'hidden' in opt.walker_opts
    for root in roots:
        root = root or '.'
        root_abs = os.path.abspath(root)
        root_prefix = '' if root == '.' else (root.rstrip('/') + '/')
        for dirpath, dirnames, filenames in os.walk(root_abs, followlinks=('follow' in opt.walker_opts)):
            # prune skipped and hidden dirs unless requested
            kept=[]
            for d in sorted(dirnames):
                if d in opt.walker_skip:
                    continue
                if d.startswith('.') and not traverse_hidden:
                    continue
                kept.append(d)
            dirnames[:] = kept
            rel_dir = os.path.relpath(dirpath, root_abs)
            rel_dir = '' if rel_dir == '.' else rel_dir + '/'
            if include_dirs and rel_dir:
                lines.append(root_prefix + rel_dir)
            for f in sorted(filenames):
                if f in opt.walker_skip:
                    continue
                # fzf shows hidden files at the root even without hidden, but does not descend into hidden dirs.
                path = root_prefix + rel_dir + f
                if include_files:
                    lines.append(path)
    return ('\n'.join(lines) + ('\n' if lines else '')).encode()

def split_fields(line: str, delimiter: str | None):
    if delimiter is None:
        fields = [m.group(0) for m in re.finditer(r'\S+', line)]
        return fields, [' '] * max(0, len(fields)-1) + [''], ' '
    try:
        pattern = re.compile(delimiter)
    except re.error:
        pattern = re.compile(re.escape(delimiter))
    fields=[]; delims=[]; pos=0; first_delim=None
    for m in pattern.finditer(line):
        fields.append(line[pos:m.start()])
        d = m.group(0)
        delims.append(d)
        if first_delim is None:
            first_delim=d
        pos=m.end()
        # Avoid infinite loops on zero-width delimiters.
        if m.start() == m.end():
            break
    fields.append(line[pos:])
    delims.append('')
    return fields, delims, (first_delim if first_delim is not None else delimiter)

def index_to_pos(idx: int, n: int):
    if idx > 0:
        return idx
    if idx < 0:
        return n + idx + 1
    return 0

def field_range(expr: str, fields_count: int):
    if '..' in expr:
        a,b = expr.split('..')
        start = 1 if a == '' else index_to_pos(int(a), fields_count)
        end = fields_count if b == '' else index_to_pos(int(b), fields_count)
        # fzf treats some over-negative range starts as invalid; keep a pragmatic check.
        if (a.startswith('-') and start < 1):
            raise FzfError('invalid format: ' + expr)
        start = max(1, start); end = min(fields_count, end)
        if start > end or end < 1 or start > fields_count:
            return []
        return list(range(start, end+1))
    else:
        pos = index_to_pos(int(expr), fields_count)
        if pos < 1 or pos > fields_count:
            return []
        return [pos]

def render_field_indices(line, delimiter, expr, ordinal=0, for_template=False):
    fields, delims, joiner = split_fields(line, delimiter)
    if expr == 'n':
        return str(ordinal)
    idxs = field_range(expr, len(fields))
    if not idxs:
        return ''
    # For a contiguous range, preserve original delimiters inside the range.
    if len(idxs) > 1 and idxs == list(range(idxs[0], idxs[-1]+1)):
        start=idxs[0]-1; end=idxs[-1]-1
        s=''
        for k in range(start, end):
            s += fields[k] + (delims[k] if k < len(delims) else joiner)
        s += fields[end]
        return s
    return joiner.join(fields[i-1] if 1 <= i <= len(fields) else '' for i in idxs)

def apply_field_exprs(line: str, spec: str | None, delimiter: str | None, ordinal=0):
    if spec is None:
        return line
    if '{' in spec and '}' in spec:
        def repl(m):
            content=m.group(1)
            if valid_placeholder(content):
                return render_field_indices(line, delimiter, content, ordinal, True)
            return m.group(0)
        return re.sub(r'\{([^{}]*)\}', repl, spec)
    outs=[]
    for part in spec.split(','):
        outs.append(render_field_indices(line, delimiter, part, ordinal))
    # Multiple expressions are joined with the active delimiter (space for AWK-style).
    _,_,joiner = split_fields(line, delimiter)
    return joiner.join(outs)

def prepare_items(records, opt: Options):
    # Exclude header lines from candidate set.
    candidates = []
    for idx, rec in enumerate(records):
        if idx < opt.header_lines:
            continue
        visible = strip_ansi(rec) if opt.ansi else rec
        candidates.append(Item(original=visible, ordinal=idx, order=len(candidates)))
    if opt.tail is not None:
        candidates = candidates[-opt.tail:] if opt.tail > 0 else []
    if opt.tac:
        candidates = list(reversed(candidates))
    for order, item in enumerate(candidates):
        item.order = order
        item.display = apply_field_exprs(item.original, opt.with_nth, opt.delimiter, item.ordinal) if opt.with_nth else item.original
        item.search = apply_field_exprs(item.display, opt.nth, opt.delimiter, item.ordinal) if opt.nth else item.display
        item.output = apply_field_exprs(item.original, opt.accept_nth, opt.delimiter, item.ordinal) if opt.accept_nth else item.original
    return candidates

# ----------------------------- Matching -----------------------------

@dataclass
class Term:
    text: str
    kind: str = 'fuzzy'  # fuzzy, exact, prefix, suffix, boundary
    inverse: bool = False

def tokenize_extended(q: str):
    tokens=[]; buf=[]; esc=False
    for ch in q:
        if esc:
            if ch == ' ':
                buf.append(' ')
            else:
                buf.append(ch)
            esc=False
            continue
        if ch == '\\':
            esc=True; continue
        if ch.isspace():
            if buf:
                tokens.append(''.join(buf)); buf=[]
        else:
            buf.append(ch)
    if esc:
        buf.append('\\')
    if buf:
        tokens.append(''.join(buf))
    return tokens

def parse_term(tok: str, opt: Options):
    if tok == '' or tok == '!':
        return None
    inv=False
    if tok.startswith('!') and len(tok) > 1:
        inv=True; tok=tok[1:]
    # Inverse terms are exact by default; normal terms obey --exact.
    default_kind = 'exact' if (opt.exact or inv) else 'fuzzy'
    kind = default_kind
    if tok.startswith("'") and len(tok) > 1:
        if tok.endswith("'") and len(tok) > 2:
            kind='boundary'; tok=tok[1:-1]
        else:
            tok=tok[1:]
            # In exact mode quote prefix unquotes the term back to fuzzy.
            kind='fuzzy' if opt.exact and not inv else 'exact'
    if tok.startswith('^') and len(tok) > 1:
        kind='prefix'; tok=tok[1:]
    if tok.endswith('$') and len(tok) > 1:
        if kind == 'prefix':
            kind='prefix_suffix'
        else:
            kind='suffix'
        tok=tok[:-1]
    return Term(tok, kind, inv)

def parse_query(q: str, opt: Options):
    if q == '':
        return []
    if not opt.extended:
        return [[Term(q, 'exact' if opt.exact else 'fuzzy', False)]]
    tokens = tokenize_extended(q)
    # Leading | behaves as a literal token in fzf; this makes the whole query very likely fail.
    if tokens and tokens[0] == '|':
        t = parse_term('|', opt)
        rest=[t] if t else []
        for tok in tokens[1:]:
            tt=parse_term(tok,opt)
            if tt: rest.append(tt)
        return [rest]
    groups=[]; cur=[]
    for tok in tokens:
        if tok == '|':
            if cur:
                groups.append(cur); cur=[]
            continue
        t = parse_term(tok, opt)
        if t: cur.append(t)
    if cur:
        groups.append(cur)
    return groups

def char_bonus(text, i, scheme='default'):
    if i <= 0:
        return 9
    prev = text[i-1]
    ch = text[i]
    if prev in '/\\':
        return 11 if scheme == 'path' else 9
    if prev in ' \t\n-:;.,|':
        return 8
    if prev == '_':
        return 6
    if prev.islower() and (ch.isupper() or ch.isdigit()):
        return 7
    return 0

def fuzzy_match(pattern: str, text: str, scheme='default'):
    if pattern == '':
        return True, 0, 0, -1, 0, []
    if len(pattern) > len(text):
        return False, 0, 0, -1, 0, []
    m=len(pattern); n=len(text)
    NEG=-10**9
    # dp[j][i] best score matching pattern[0:j+1] ending at text i
    dp=[[NEG]*n for _ in range(m)]
    prev_idx=[[-1]*n for _ in range(m)]
    for i,ch in enumerate(text):
        if ch == pattern[0]:
            dp[0][i] = 16 + char_bonus(text, i, scheme)*2 - i
    for j in range(1,m):
        best_score=NEG; best_pos=-1
        for i,ch in enumerate(text):
            if i > 0 and dp[j-1][i-1] > NEG:
                # candidate previous just before i
                pass
            # update best previous from i-1 before using i
            if i > 0 and dp[j-1][i-1] > NEG:
                cand = dp[j-1][i-1]
                if cand > best_score:
                    best_score=cand; best_pos=i-1
            if ch != pattern[j] or best_pos < 0:
                continue
            gap = i - best_pos - 1
            gap_pen = 0 if gap == 0 else (-3 - max(0,gap-1))
            consec = 8 if gap == 0 else 0
            score = best_score + 16 + char_bonus(text, i, scheme) + consec + gap_pen
            dp[j][i]=score; prev_idx[j][i]=best_pos
    best=NEG; end=-1
    for i,score in enumerate(dp[m-1]):
        if score > best:
            best=score; end=i
    if end < 0:
        return False, 0, 0, -1, 0, []
    pos=[end]
    j=m-1; cur=end
    while j>0:
        p=prev_idx[j][cur]
        pos.append(p); cur=p; j-=1
    pos.reverse()
    begin=pos[0]; end=pos[-1]
    # Small bonuses/penalties that make common fzf rankings closer.
    chunk=end-begin+1
    score=best - len(text)//4
    return True, score, begin, end, chunk, pos

def exact_occurrences(pattern, text):
    if pattern == '':
        return [0]
    out=[]; start=0
    while True:
        i=text.find(pattern,start)
        if i<0: break
        out.append(i); start=i+1
    return out

def boundary_score_at(text, start, pat_len):
    end = start + pat_len
    before = text[start-1] if start>0 else ''
    after = text[end] if end < len(text) else ''
    def b(c, side):
        if c == '': return 10
        if c.isalnum(): return 0
        if c == '_': return 5
        return 9
    return b(before,'l') + b(after,'r')

def exact_match(pattern: str, text: str, kind='exact', scheme='default'):
    if pattern == '':
        return True, 0, 0, -1, 0, []
    occ=[]
    if kind == 'prefix':
        if text.startswith(pattern): occ=[0]
    elif kind == 'suffix':
        if text.endswith(pattern): occ=[len(text)-len(pattern)]
    elif kind == 'prefix_suffix':
        if text == pattern: occ=[0]
    elif kind == 'boundary':
        for i in exact_occurrences(pattern,text):
            if boundary_score_at(text,i,len(pattern)) > 0 and \
               (i == 0 or not text[i-1].isalnum()) and \
               (i+len(pattern) == len(text) or not text[i+len(pattern)].isalnum()):
                occ.append(i)
    else:
        occ=exact_occurrences(pattern,text)
    if not occ:
        return False,0,0,-1,0,[]
    best_tuple=None
    for i in occ:
        end=i+len(pattern)-1
        bonus=char_bonus(text,i,scheme)
        if kind == 'boundary':
            bonus += boundary_score_at(text,i,len(pattern))
        score = 16*len(pattern) + bonus*2 - i - len(text)//6
        if kind in ('prefix','prefix_suffix'):
            score += 20
        if kind in ('suffix','prefix_suffix'):
            score += 10
        if scheme == 'path' and '/' in text[:i]:
            # Prefer occurrences in the tail path element.
            score += 8
        tup=(score,i,end,len(pattern),list(range(i,end+1)))
        if best_tuple is None or tup[0] > best_tuple[0]:
            best_tuple=tup
    score,i,end,chunk,pos=best_tuple
    return True,score,i,end,chunk,pos

@dataclass
class MatchResult:
    item: Item
    score: int
    begin: int
    end: int
    chunk: int
    matched: bool=True

def term_match(term: Term, item_text: str, ignore_case: bool, opt: Options):
    pat = normalize_for_match(term.text, ignore_case, opt.literal)
    txt = normalize_for_match(item_text, ignore_case, opt.literal)
    if term.kind == 'fuzzy':
        return fuzzy_match(pat, txt, opt.scheme)
    return exact_match(pat, txt, term.kind, opt.scheme)

def match_item(item: Item, groups, ignore_case, opt: Options):
    if groups == []:
        return MatchResult(item,0,0,-1,0)
    best=None
    for group in groups:
        ok=True; score=0; begin=10**9; end=-1; chunk=10**9
        for term in group:
            m, sc, b, e, ch, pos = term_match(term, item.search, ignore_case, opt)
            if term.inverse:
                if m:
                    ok=False; break
                else:
                    continue
            if not m:
                ok=False; break
            score += sc
            begin=min(begin,b); end=max(end,e); chunk=min(chunk,ch)
        if ok:
            if begin == 10**9: begin=0; chunk=0
            res=MatchResult(item, score, begin, end, chunk)
            if best is None or res.score > best.score:
                best=res
    return best

def pathname_key(s, begin):
    # prefer matches in basename; then shorter directory depth
    slash=s.rfind('/',0,begin+1)
    in_base = 0 if slash >= 0 else 1
    # for sorting ascending: basename match should be 0
    return 0 if slash >= 0 else 1

def sort_matches(matches, opt: Options, query_empty=False):
    if opt.no_sort or query_empty:
        return sorted(matches, key=lambda m: m.item.order)
    criteria = opt.tiebreak[:] if opt.tiebreak else ['length']
    if 'index' not in criteria:
        criteria.append('index')
    def key(m):
        parts=[-m.score]
        for c in criteria:
            if c == 'length':
                parts.append(len(m.item.search))
            elif c == 'chunk':
                parts.append(m.chunk)
            elif c == 'pathname':
                # prefer matches after the last slash (basename), then fewer chars after begin
                last=m.item.search.rfind('/')
                parts.append(0 if m.begin > last else 1)
                parts.append(len(m.item.search) - last)
            elif c == 'begin':
                parts.append(m.begin)
            elif c == 'end':
                parts.append(-m.end)
            elif c == 'index':
                parts.append(m.item.order)
        return tuple(parts)
    return sorted(matches, key=key)

def filter_items(items, query, opt: Options):
    ignore_case = (opt.case_mode == 'ignore') or (opt.case_mode == 'smart' and not has_upper(query))
    groups=parse_query(query,opt)
    matches=[]
    for item in items:
        res=match_item(item, groups, ignore_case, opt)
        if res is not None:
            matches.append(res)
    return sort_matches(matches,opt,query_empty=(query==''))

# ----------------------------- Interactive -----------------------------

def tty_failed():
    eprint('inappropriate ioctl for device')
    return 2

def key_name(ch):
    if ch in ('\r','\n'):
        return 'enter'
    if ch == '\t': return 'tab'
    if ch == '\x1b': return 'esc'
    o=ord(ch)
    if 1 <= o <= 26:
        return 'ctrl-' + chr(ord('a')+o-1)
    if ch == '\x7f': return 'backspace'
    return ch

def minimal_interactive(items, opt: Options):
    if not sys.stdin.isatty() or not sys.stderr.isatty():
        return tty_failed()
    try:
        import termios, tty, select
    except Exception:
        return tty_failed()
    fd=sys.stdin.fileno()
    old=termios.tcgetattr(fd)
    query=opt.query
    cursor=0
    selected=set()
    try:
        tty.setraw(fd)
        sys.stderr.write('\x1b[?25l')
        def redraw():
            nonlocal cursor
            ms=filter_items(items,query,opt)
            if cursor >= len(ms): cursor=max(0,len(ms)-1)
            sys.stderr.write('\x1b[2J\x1b[H')
            sys.stderr.write(opt.prompt + query + '\r\n')
            for idx,m in enumerate(ms[:10]):
                mark='>' if idx==cursor else ' '
                multi='*' if m.item.order in selected else ' '
                sys.stderr.write(f'{mark}{multi} {m.item.display[:200]}\r\n')
            sys.stderr.flush()
            return ms
        matches=redraw()
        while True:
            ch=sys.stdin.read(1)
            name=key_name(ch)
            if opt.expect and name in opt.expect:
                keyout=name
                break
            if name in ('ctrl-c','ctrl-g','esc'):
                sys.stderr.write('\x1b[?25h\x1b[2J\x1b[H'); sys.stderr.flush()
                return 130
            if name == 'enter':
                keyout='' if opt.expect else None
                break
            if name in ('ctrl-j','ctrl-n'):
                cursor += 1
            elif name in ('ctrl-k','ctrl-p'):
                cursor -= 1
            elif name == 'tab' and opt.multi_enabled:
                if matches:
                    selected.add(matches[cursor].item.order)
                    cursor += 1
            elif name == 'backspace':
                query=query[:-1]
            elif len(ch)==1 and ord(ch) >= 32:
                query += ch
            matches=redraw()
        sys.stderr.write('\x1b[?25h\x1b[2J\x1b[H'); sys.stderr.flush()
    finally:
        try: termios.tcsetattr(fd, termios.TCSADRAIN, old)
        except Exception: pass
    matches=filter_items(items,query,opt)
    out=[]
    if opt.print_query:
        out.append(query)
    if opt.expect:
        out.append(keyout or '')
    if opt.multi_enabled and selected:
        by_order={m.item.order:m for m in matches}
        for order in sorted(selected):
            if order in by_order:
                out.append(by_order[order].item.output)
    elif matches:
        out.append(matches[0].item.output)
    output_bytes(out,opt)
    return 0 if (matches or opt.print_query or opt.expect) else 1

# ----------------------------- Shell integration stubs -----------------------------

def shell_integration(kind):
    ext={'bash':'bash','zsh':'zsh','fish':'fish'}[kind]
    art = """#     ____      ____
#    / __/___  / __/
#   / /_/_  / / /_
#  / __/ / /_/ __/
# /_/   /___/_/ key-bindings.%s
#
# - $FZF_TMUX_OPTS
# - $FZF_CTRL_T_COMMAND
# - $FZF_CTRL_T_OPTS
# - $FZF_CTRL_R_COMMAND
# - $FZF_CTRL_R_OPTS
# - $FZF_ALT_C_COMMAND
# - $FZF_ALT_C_OPTS
""" % ext
    if kind == 'bash':
        body = """### key-bindings.bash ###
%s
if [[ $- =~ i ]]; then
  # Minimal fzf shell integration generated by this reimplementation.
  bind -x '"\\C-t": fzf >/dev/null'
fi

### completion.bash ###
_fzf_complete() { :; }
""" % art
    elif kind == 'zsh':
        body = """### key-bindings.zsh ###
%s
# Key bindings
# ------------
if [[ -o interactive ]]; then
  bindkey '^T' fzf-file-widget 2>/dev/null || true
fi

### completion.zsh ###
_fzf_complete() { :; }
""" % art
    else:
        body = """### key-bindings.fish ###
%s
# Key bindings
# ------------
function fzf_key_bindings
end

### completion.fish ###
complete -c fzf -f
""" % art
    return body

# ----------------------------- Main -----------------------------

def build_argv():
    default_opts = os.environ.get('FZF_DEFAULT_OPTS')
    args=[]
    if default_opts is not None and default_opts != '':
        try:
            args.extend(shell_split_options(default_opts, '$FZF_DEFAULT_OPTS'))
        except FzfError as e:
            raise
    elif os.environ.get('FZF_DEFAULT_OPTS_FILE'):
        path=os.environ.get('FZF_DEFAULT_OPTS_FILE')
        try:
            text=open(path,'r').read()
        except OSError as ex:
            raise FzfError(f"$FZF_DEFAULT_OPTS_FILE: open {path}: {ex.strerror.lower() if ex.strerror else ex}")
        try:
            args.extend(shell_split_options(text, '$FZF_DEFAULT_OPTS_FILE'))
        except FzfError:
            raise
    args.extend(sys.argv[1:])
    return args

def main():
    try:
        argv=build_argv()
        opt=parse_args(argv)
    except FzfError as e:
        msg=str(e)
        # Prefix parser errors from env option contents.
        env = os.environ.get('FZF_DEFAULT_OPTS')
        if env and not msg.startswith('$FZF_DEFAULT_OPTS') and any(bad in env for bad in ['--no-such']):
            msg = '$FZF_DEFAULT_OPTS: ' + msg
        eprint(msg)
        return 2
    if opt.show_version:
        print(VERSION)
        return 0
    if opt.show_help:
        sys.stdout.write(HELP_TEXT)
        return 0
    if opt.show_man:
        # The benchmark environment's man command prints this minimized-system notice.
        sys.stdout.write(MAN_FALLBACK)
        return 0
    if opt.shell:
        sys.stdout.write(shell_integration(opt.shell))
        return 0

    records=read_records(opt)
    items=prepare_items(records,opt)

    if opt.filter_query is not None:
        query=opt.filter_query
        matches=filter_items(items,query,opt)
        out=[]
        if opt.print_query:
            out.append(query)
        out.extend(m.item.output for m in matches)
        output_bytes(out,opt)
        return 0 if matches else 1

    # Automatic scripting decisions before opening the terminal.
    query=opt.query
    if opt.select1 or opt.exit0:
        matches=filter_items(items,query,opt)
        if opt.exit0 and len(matches) == 0:
            out=[]
            if opt.print_query: out.append(query)
            if opt.expect: out.append('')
            output_bytes(out,opt)
            return 1
        if opt.select1 and len(matches) == 1:
            out=[]
            if opt.print_query: out.append(query)
            if opt.expect: out.append('')
            out.append(matches[0].item.output)
            output_bytes(out,opt)
            return 0
    return minimal_interactive(items,opt)

if __name__ == '__main__':
    sys.exit(main())
